   "he": {
    "title": "עוצמת קרינת UV מול הספק ה-LED המפוקד — 405 nm, StarBright על ה-USB של המכונה",
    "purpose": "למדוד את עוצמת הקרינה שהתא מספק בפועל בכל הספק LED מפוקד ב-405 nm — מ-30 עד 100% במדרגות של 10% — כשה-Ophir StarBright מחובר ישירות למכונה, ולשרטט את עוצמת הקרינה הנמדדת מול הפקודה. התוכנה מתייחסת לפקודה כהספק מערכת מכויל; זו העקומה שאומרת אם זה נכון, בכל יחידה: מונוטונית, עד כמה ליניארית, ואיך ה-mW/cm2 לכל אחוז יורד לקראת 100% כשהלדים מתחממים.\n",
    "sample_rationale": null,
    "safety_plan": null,
    "preconditions": [
     "כבל ה-USB של ה-StarBright מחובר ליציאת USB פנויה של המכונה (לא של מחשב הקונסולה), המד מופעל",
     "המד מכוון ל-405 nm במד עצמו (Setup ← Wavelength)",
     "ראש ה-UV במרכז התא על משטח הבנייה, מופנה מעלה אל הלדים, הכבל עובר דרך אטם הדלת; הדלת סגורה ונעולה",
     "התא בטמפרטורת הסביבה, הלדים קרים (ללא קיור ב-15 הדקות האחרונות); כל ארבעת מקדמי הכיול של הלדים בערכי הייצור"
    ],
    "steps": [
     "הרץ את הבדיקה. הקונסולה בודקת קודם את ה-StarBright דרך המכונה — מחובר, מספק קריאה, מכוון ל-405 nm (ההרצה נשארת נעולה עד אז) — ואז המכונה לוקחת קריאת חושך, מדרגת את הלדים 30, 40, 50, 60, 70, 80, 90, 100% ב-405 nm, 10 שניות למדרגה, קוראת את המד ב-5 Hz, ומכבה אותם. כל ערך, היומן (CSV) וגרף עוצמת הקרינה מול הפקודה נרשמים אוטומטית; לא מקלידים כלום"
    ],
    "equipment": [
     "מד הספק Ophir StarBright עם ראש פוטודיודה ל-UV (למשל PD300RM-8W) וכבל ה-USB שלו",
     "מתקן אחיזה לראש החיישן במרכז התא, מופנה אל הלדים"
    ],
    "cases": [],
    "notes": {
     "meter_detected": "המכונה רואה את ה-StarBright ב-USB שלה",
     "meter_head": "head model and serial as reported by the meter",
     "meter_wavelength_nm": "מה שהמד מכוון אליו, נקרא בחזרה על ידי המכונה",
     "meter_wavelength_verified": "הגדרת המד == 405 nm לפני הסריקה",
     "dark_mw_cm2": "לדים כבויים",
     "all_steps_measured": "לכל מדרגה יש ערך מיוצב",
     "max_dev_pct": "הסטייה הגדולה ביותר מההתאמה, כאחוז מהערך המותאם ב-100%",
     "gain_30": "עוצמת קרינה / פקודה ב-30%",
     "gain_100": "עוצמת קרינה / פקודה ב-100% — נמוך מ-gain_30 כשהעקומה מתעקלת",
     "monotonic": "כל מדרגה קוראת גבוה יותר מהקודמת",
     "led_max_c": "התרמיסטור החם ביותר של הלדים בסוף מדרגת ה-100%"
    }
   }
